"""`t0 gen [--check] [--scope toolkit|repo|workspace|kb]` - every generated file, from one TARGETS table.

Sources (the only hand-written inputs):
  pyproject.toml                    name/version/description -> both plugin manifests (version single-sourced)
  plugin/skills/<name>/SKILL.md     hand-written bodies; frontmatter subset: name, description (<=300),
                                    argument-hint, user-invocable, disable-model-invocation, metadata.credits,
                                    metadata.t0 {requires_bet: bool, bucket: str, ships: 'v0.1'|'v0.2'|...}
  plugin/skills/_shared/*.md        header (output language + KB rule) and footer (`t0 log` + stop rules)
  t0/hooks.py HOOKS                 hook table (event, matcher, hook name)
  t0/profile/table.py REGISTRY      profile.md, JSON schemas, templates, index sections
  vendor/upstream/**                pristine upstream copies (mattpocock 1.3.1, pstack 0.15.25) + LICENSE

Generated (all carry '<!-- generated by t0 gen; edit the source -->' or a JSON "$comment"):
  scope toolkit:
    plugin/.claude-plugin/plugin.json          Claude manifest (explicit skills list from metadata.t0.ships)
    plugin/plugin.json                         Agent Plugins 1.0 ($schema, keywords) for Copilot + Kiro power
    plugin/hooks/hooks.json                    Claude format (Copilot CLI + VS Code read it too)
    plugin/mcp.json, plugin/.mcp.json          {"mcpServers": {"t0-kb": {"command": "t0", "args": ["mcp"]}}}
    plugin/skills/*/SKILL.md  [regions]        header/footer regions between <!-- t0:gen:* --> markers
    plugin/.claude-plugin/marketplace.json     internal marketplace entry
    templates/okf-kb/profile.md                from REGISTRY
    templates/okf-kb/.t0/schemas/<type>.json   JSON Schema per type (editor validation; derived)
    evals/mocks/t0-kb/<tool>.md                recorded from the REAL t0 mcp over tests/fixtures/kb-payments
    THIRD_PARTY_NOTICES.md                     from vendor/upstream/*/LICENSE + metadata.credits
    docs/skills.md                             human page: name, purpose, t0 calls (from SKILL.md frontmatter)
  scope repo (`t0 setup` in a product repo):
    AGENTS.md t0 block, CLAUDE.md pointer, .github/copilot-instructions.md pointer, .kiro/steering/t0.md,
    .github/hooks/t0.json (cloud agent), .github/workflows/t0.yml, copilot-setup-steps.yml (opt-in),
    .githooks/pre-push -> `t0 hook pre-push`, .gitignore '.kb/'
  scope workspace (`t0 ws init|sync`, `t0 bet start|use`):
    AGENTS.md (card), .t0/{workspace,bet}.json, .t0/env.sh, .vscode/{settings,tasks}.json,
    .kiro/steering/t0.md, .kiro/hooks/t0.json
  scope kb (`t0 setup --kb`):
    .github/workflows/{kb-check,kb-render,kb-batch,jira-reconcile}.yml, CODEOWNERS skeleton (gates/** owners)

--check renders to memory, diffs against disk, exits 1 listing paths (CI in toolkit, product repos, KB).
Also verifies vendor/upstream sha256 == metadata.credits.sha256 for every forked skill.
"""
from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from pathlib import Path
from typing import Callable


class Tool(Enum):
    CLAUDE = "claude"; COPILOT = "copilot"; KIRO = "kiro"; ALL = "all"; NONE = "none"


class Scope(Enum):
    TOOLKIT = "toolkit"; REPO = "repo"; WORKSPACE = "workspace"; KB = "kb"


@dataclass(frozen=True)
class GenContext:
    root: Path
    scope: Scope
    facts: dict                 # scope-specific parsed inputs (workspace manifest, product, handle...)


@dataclass(frozen=True)
class Target:
    tool: Tool
    scope: Scope
    path: str                   # relative to GenContext.root; may contain {vars}
    render: Callable[[GenContext], str | None]   # None = not applicable (e.g. cloud-agent steps opt-out)
    region: str | None = None   # update only between <!-- t0:gen:<region> --> markers (AGENTS.md, SKILL.md)


TARGETS: tuple[Target, ...] = ()   # implementation: one entry per file listed above


@dataclass(frozen=True)
class Drift:
    path: str
    reason: str                 # 'missing' | 'differs' | 'upstream-sha-mismatch' | 'orphan-generated'


def generate(ctx: GenContext) -> dict[str, str]:
    """Pure: path -> content for every applicable target."""
    raise NotImplementedError


def write(ctx: GenContext, rendered: dict[str, str]) -> list[str]:
    raise NotImplementedError


def check_drift(ctx: GenContext) -> list[Drift]:
    raise NotImplementedError
